import{_ as i,l,o as t,c as n,v as e,p as s,x as o,d as A,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"AutoGPT 架构笔记","description":"","frontmatter":{"title":"AutoGPT 架构笔记","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/autogpt-arch.md","filePath":"llm/autogpt-arch.md","lastUpdated":1789023840000}'),d={name:"llm/autogpt-arch.md"};function u(c,a,p,P,m,T){const r=l("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="autogpt-架构笔记" tabindex="-1">AutoGPT 架构笔记 <a class="header-anchor" href="#autogpt-架构笔记" aria-label="Permalink to &quot;AutoGPT 架构笔记&quot;">​</a></h1><div class="epigraph"><p>把一个自然语言目标交给循环：想、计划、批评、再选一条命令；记忆与工具在循环外，模型本身并不持有环境状态。</p><footer>—— 对照 Significant Gravitas，Auto-GPT 开源项目（2023）及后续 LLM 自主代理综述对该环路的抽象</footer></div><p>2023 年 3 月前后，Significant Gravitas（Toran Bruce Richards）发布的 Auto-GPT 把「给语言模型一个目标，让它自己拆任务、调工具、写文件」做成可运行的开源循环，而不是一篇会议论文。它迅速成为自主代理的公众样本：用户只写高层目标，进程在搜索、浏览、读写工作区、执行代码之间迭代，直到自认为完成或撞上步数与预算上限。学术侧随后用 Wang 等人的代理综述（arXiv:2308.11432）一类框架把它收成「规划 + 记忆 + 工具 + 剖析」四件套。本篇写这套架构的模块边界与失败模式。不写未授权访问、漏洞利用或把浏览工具指向他人受保护系统；默认工作区是用户自己的沙箱目录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对话补全一次生成一段答复就结束。自主任务却要跨越许多环境步骤：先查资料，再落成笔记，再根据笔记改计划。若只靠一次超长 CoT，模型既看不到网页的真实返回，也无法把中间产物存成可检索的文件。Auto-GPT 要回答的工程问题是：在<strong>不改基座权重</strong>的前提下，用提示格式、命令表和外部存储，把单轮补全接成可中断的控制回路。</p><p>另一半问题是状态。上下文窗口装不下整段轨迹；纯窗口内记忆会把早期目标挤出去，代理开始重复搜索或忘掉约束。需要把「当前思考」和「可检索的长期笔记」分开，并把环境副作用（文件、命令输出）当成观察而不是模型内隐状态。这与 <a href="/llm/react">ReAct</a> 同构，但 Auto-GPT 把 Thought / Plan / Criticism 写成固定字段，并把命令做成可解析的 JSON，而不是自由格式的 <code>Action:</code> 行。</p><h3 id="目标在循环外-命令在循环内" tabindex="-1">目标在循环外，命令在循环内 <a class="header-anchor" href="#目标在循环外-命令在循环内" aria-label="Permalink to &quot;目标在循环外，命令在循环内&quot;">​</a></h3><p>用户目标是不变量，应反复出现在系统前缀里，而不是只在第一轮说一次。循环内变化的是：短期记忆（最近若干步的思考与观察）、长期记忆检索结果、以及下一条要执行的命令名与参数。若把目标写进可被模型随意改写的「内部独白」而不回灌，代理会在中途改写成功标准——这是早期演示里常见的跑偏，不是模型突然变聪明。</p><p><span class="marginnote">引用开源仓库与版本日期，不要把博客演示的「全自动创业」当成评测合同。Auto-GPT 没有 SWE-bench 式的官方 resolved 率；后继工作应写清骨干模型、工具白名单与最大迭代，而不是复述 2023 年的 Star 数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型一拍包含若干文本槽：思考（当前局势）、推理（为什么）、计划（接下来几步）、批评（计划的漏洞）、对用户说的话、以及一条结构化命令。宿主解析命令名，在白名单里分发：网页搜索、打开 URL 抽取正文、读写工作区文件、运行解释器、或结束。执行结果截断后写回下一轮，作为观察。命令表刻意小于 Unix：减少动作空间，使解析稳定。插件后来把天气、邮箱一类 API 接进同一槽位，但架构没有变——仍是「模型提议、宿主执行」。</p><p>长期记忆常用向量库：把过去的笔记、摘要、文件片段嵌入，按当前思考检索若干条塞进提示。短期记忆是滑动窗口或摘要压缩。规划不是一次生成整棵任务树再执行到底，而是每步重写近端计划；这更接近反应式循环，而不是经典 STRIPS 规划器。多实例变体（「招聘一个研究员代理」）只是再开一条相同循环，用消息当接口，并没有新的形式化语义。</p>',12)),(t(),s(h,null,{default:o(()=>[E(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E7%94%A8%E6%88%B7%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20P%5B%22%E6%80%9D%E8%80%83%20%2F%20%E8%AE%A1%E5%88%92%20%2F%20%E6%89%B9%E8%AF%84%22%5D%0A%20%20M%5B%22%E9%95%BF%E6%9C%9F%E8%AE%B0%E5%BF%86%E6%A3%80%E7%B4%A2%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20C%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E5%91%BD%E4%BB%A4%22%5D%0A%20%20C%20--%3E%20H%5B%22%E5%AE%BF%E4%B8%BB%E7%99%BD%E5%90%8D%E5%8D%95%E6%89%A7%E8%A1%8C%22%5D%0A%20%20H%20--%3E%20O%5B%22%E6%88%AA%E6%96%AD%E8%A7%82%E5%AF%9F%22%5D%0A%20%20O%20--%3E%20MEM%5B%22%E5%86%99%E5%85%A5%E8%AE%B0%E5%BF%86%22%5D%0A%20%20MEM%20--%3E%20P%0A%20%20H%20--%3E%20D%7B%E7%BB%93%E6%9D%9F%3F%7D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20P%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20F%5B%22%E6%B1%87%E6%80%BB%E7%AD%94%E5%A4%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="命令解析必须是宿主的责任" tabindex="-1">命令解析必须是宿主的责任 <a class="header-anchor" href="#命令解析必须是宿主的责任" aria-label="Permalink to &quot;命令解析必须是宿主的责任&quot;">​</a></h3><p>模型输出的 JSON 经常缺字段、把搜索查询写成散文。解析失败应作为观察返回「非法命令」，而不是在宿主里用启发式猜一个副作用。结束命令要显式，避免代理在已完成时继续烧搜索额度。步数、墙钟、工具调用次数都是硬上限；没有上限的循环会在重复搜索上耗尽账单。这些约束属于运行时，写进论文式架构图时不应省略。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Auto-GPT 并不给模型新的作用子。每一拍仍是一次条件生成：前缀 = 目标 + 工具说明书 + 记忆片段 + 最近轨迹。Thought / Plan / Criticism 的作用是占用上下文当工作记忆，使下一条命令对「刚才怎么批评自己」条件化，类似于 ReAct 的 Thought。真正改变世界的是宿主侧执行。记忆库改变的是下一拍能看见什么，不改变权重。因此换模型要重调提示与命令名；换向量模型要重建索引。把「Auto-GPT 会自主」理解成权重里出现了规划模块，是类别错误。</p><h3 id="失败主要来自观察与目标漂移" tabindex="-1">失败主要来自观察与目标漂移 <a class="header-anchor" href="#失败主要来自观察与目标漂移" aria-label="Permalink to &quot;失败主要来自观察与目标漂移&quot;">​</a></h3><p>搜索返回广告和目录页，浏览抽取丢掉正文，文件越写越长却没有人读——观察质量差时，批评槽会一本正经地基于错误网页做推理。目标漂移则是：批评与计划在窗口里互相改写成功标准，而用户目标没有每步回灌。向量记忆还会检索到语义近但任务无关的旧笔记，造成主题跳跃。这些不是「再加一个插件」能修的；要修的是观察截断策略、目标回灌、以及检索的过滤。</p><p><span class="marginnote">BabyAGI 把循环收得更短（任务队列 + 执行 + 再规划），强调待办列表而不是长篇自我批评。二者同属 2023 年提示式自主代理，不要把队列调度写成 Auto-GPT 的内部实现。评测应冻结工具与步数，否则「更会规划」只是更会烧 token。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="演示闭环不是基准分数" tabindex="-1">演示闭环不是基准分数 <a class="header-anchor" href="#演示闭环不是基准分数" aria-label="Permalink to &quot;演示闭环不是基准分数&quot;">​</a></h3><p>Auto-GPT 证明了脚手架可以让对话模型看起来像代理，没有证明该脚手架在 WebArena、OSWorld 或 SWE-bench 上可复现地赢。后续 SWE-agent、OpenHands 把接口收成软件工程原语，分数才变得可引用。继续用 Auto-GPT 当「通用智能体」基线时，必须声明：它是控制回路样本，不是 SOTA 数字来源。成本上，每步多次补全（思考槽很长）会把同一工具调用的价格乘起来；生产系统更常改成单次 function calling。</p><p>权限上，解释器与文件系统必须锁在工作区；网络工具应有域名与方法白名单。架构图里把「browse」画成万能浏览器，不等于产品可以让模型打开任意登录页去代用户操作。记忆库会沉淀中间文件中的密钥与个人数据，索引与日志要按工作区隔离。这些是部署约束，不是论文贡献。</p><p><span class="marginnote">出处：Significant Gravitas，Auto-GPT（GitHub，2023 起）；循环抽象对照 Yao 等 ReAct（ICLR 2023）与 Wang 等 <em>A Survey on Large Language Model based Autonomous Agents</em>（arXiv:2308.11432）。无单一 NeurIPS 原论文定义该项目。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Auto-GPT 用固定文本槽加结构化命令，把单轮补全接成目标驱动的工具循环。</li><li>状态分三处：上下文里的短记忆、向量库里的长记忆、宿主执行后的观察。</li><li>模型只提议命令；副作用与解析失败处理属于宿主。</li><li>主要失败是观察噪声与目标漂移，不是缺少更多插件。</li><li>它是 2023 年自主代理的架构样本，不宜直接当现代 GUI / 仓库基准的 SOTA 引用。</li><li>出处：Auto-GPT 开源项目；对照 ReAct 与 LLM 代理综述 arXiv:2308.11432。</li></ul>',14))])}const g=i(d,[["render",u]]);export{_ as __pageData,g as default};
